using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    // Bronze customer is charged the basket with the Bronze reduction
    [Theory]
    [InlineData(10000, 9500)]
    [InlineData(7, 7)]
    public void Bronze_customer_is_charged_the_basket_with_the_Bronze_reduction(int subtotalCents, int expectedTotalCents)
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, LoyaltyTier.Bronze));

        Assert.Equal(expectedTotalCents, quote.TotalCents);
    }
}

